  conflicts(start, end) {
    // Validate inputs
    if (!Number.isInteger(start) || start < 0 || start >= 1440) {
      throw new Error('Start must be an integer between 0 and 1439');
    }

    if (!Number.isInteger(end) || end < 0 || end > 1440) {
      throw new Error('End must be an integer between 0 and 1440');
    }

    if (start >= end) {
      throw new Error('Start must be less than end');
    }

    // Find meetings that overlap with the given range
    // Two intervals [a,b) and [c,d) overlap if a < d and c < b
    const overlapping = this.meetings.filter(meeting => {
      return meeting.start < end && start < meeting.end;
    });

    // Sort by start time and return IDs
    return overlapping.sort((a, b) => a.start - b.start).map(meeting => meeting.id);
  }

  remove(id) {
    // Check if meeting exists
    const meeting = this.meetingMap.get(id);
    if (!meeting) {
      return false;
    }

    // Remove from meetings array
    const index = this.meetings.indexOf(meeting);
    if (index !== -1) {
      this.meetings.splice(index, 1);
    }

    // Remove from meetingMap
    this.meetingMap.delete(id);

    return true;
  }
}

// Template rendering function
function render(template, data) {
  // Simple template replacement - replace {{key}} with data[key] (HTML-escaped)
  // and {{{key}}} with data[key] (raw)
  // Supports dotted paths like {{user.name}}
  // Supports filters like {{name | upper}}, {{name | lower}}, {{name | trim}}
  // Filters can be chained like {{ name | trim | upper }}

  // First handle {{{key}}} patterns (raw insertion)
  template = template.replace(/\{\{\{([^}]+)\}\}\}/g, (match, keyPath) => {
    const keys = keyPath.split('.');
    let value = data;

    // Traverse the object using the dotted path
    for (let i = 0; i < keys.length; i++) {
      if (value === null || value === undefined) {
        return ''; // Return empty string if any part is missing
      }
      value = value[keys[i]];
    }

    // Return the value if found, otherwise return empty string
    return value !== undefined ? value : '';
  });

  // Then handle {{key}} patterns (HTML-escaped)
  return template.replace(/\{\{([^}]+)\}\}/g, (match, keyPath) => {
    const keys = keyPath.split('.');
    let value = data;

    // Traverse the object using the dotted path
    for (let i = 0; i < keys.length; i++) {
      if (value === null || value === undefined) {
        return ''; // Return empty string if any part is missing
      }
      value = value[keys[i]];
    }

    // Apply filters if present
    if (keyPath.includes('|')) {
      const parts = keyPath.split('|').map(part => part.trim());
      const mainKey = parts[0].trim();

      // Extract the value using the main key path
      let mainValue = data;
      const mainKeys = mainKey.split('.');
      for (let i = 0; i < mainKeys.length; i++) {
        if (mainValue === null || mainValue === undefined) {
          mainValue = '';
          break;
        }
        mainValue = mainValue[mainKeys[i]];
      }

      // Apply filters in order
      let result = mainValue !== undefined ? mainValue.toString() : '';

      // Define available filters
      const filters = {
        'upper': (str) => str.toUpperCase(),
        'lower': (str) => str.toLowerCase(),
        'trim': (str) => str.trim()
      };

      // Apply each filter
      for (let i = 1; i < parts.length; i++) {
        const filterName = parts[i].trim();
        if (!filters[filterName]) {
          throw new Error(`Unknown filter: ${filterName}`);
        }
        result = filters[filterName](result);
      }

      value = result;
    }

    // HTML-escape the value if found, otherwise return empty string
    if (value === undefined) {
      return '';
    }

    // HTML escape function
    const escapeHtml = (text) => {
      const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      };
      return text.toString().replace(/[&<>"']/g, (m) => map[m]);
    };

    return escapeHtml(value);
  });
}

