def where(rows, column, op, value):
    """Filter rows by column value using the specified operator.

    Args:
        rows: List of row dictionaries
        column: Column name to filter on
        op: Comparison operator ('=', '!=', '<', '>', '<=', '>=')
        value: Value to compare against

    Returns:
        List of rows where the condition is true

    Raises:
        ValueError: If op is not one of the supported operators
    """
    # Supported operators
    supported_ops = {'=', '!=', '<', '>', '<=', '>='}

    if op not in supported_ops:
        raise ValueError(f"Unknown operator: {op}")

    if not rows:
        return []

    # Check if column exists in first row
    if column not in rows[0]:
        raise KeyError(f"Column '{column}' not found")

    result = []

    for row in rows:
        # Get the column value
        col_value = row[column]

        # Try to convert both values to numbers for comparison
        try:
            # Try to parse both values as numbers
            col_num = float(col_value)
            val_num = float(value)
            # Both are numbers, do numeric comparison
            numeric_comparison = True
        except (ValueError, TypeError):
            # At least one is not a number, do string comparison
            col_num = None
            val_num = None
            numeric_comparison = False

        # Perform the comparison
        if op == '=':
            if numeric_comparison:
                match = col_num == val_num
            else:
                match = col_value == str(value)
        elif op == '!=':
            if numeric_comparison:
                match = col_num != val_num
            else:
                match = col_value != str(value)
        elif op == '<':
            if numeric_comparison:
                match = col_num < val_num
            else:
                match = col_value < str(value)
        elif op == '>':
            if numeric_comparison:
                match = col_num > val_num
            else:
                match = col_value > str(value)
        elif op == '<=':
            if numeric_comparison:
                match = col_num <= val_num
            else:
                match = col_value <= str(value)
        elif op == '>=':
            if numeric_comparison:
                match = col_num >= val_num
            else:
                match = col_value >= str(value)

        if match:
            result.append(row)

    return result


def order_by(rows, column, descending=False):
    """Sort rows by a column value.

    Args:
        rows: List of row dictionaries
        column: Column name to sort by
        descending: If True, sort in descending order (default: False)

    Returns:
        List of rows sorted by the specified column

    The sorting is numeric when all values in the column can be parsed as numbers,
    otherwise it's string sorting. Rows with equal values maintain their original order.
    """
    if not rows:
        return []

    # Check if column exists in first row
    if column not in rows[0]:
        raise KeyError(f"Column '{column}' not found")

    # Check if all values in the column can be parsed as numbers
    all_numeric = True
    for row in rows:
        try:
            float(row[column])
        except (ValueError, TypeError):
            all_numeric = False
            break

    # Create list of (index, row) pairs to maintain stable sort
    indexed_rows = list(enumerate(rows))

    # Sort based on whether all values are numeric
    if all_numeric:
        # Numeric sorting
        sorted_indexed = sorted(indexed_rows, key=lambda x: float(x[1][column]), reverse=descending)
    else:
        # String sorting
        sorted_indexed = sorted(indexed_rows, key=lambda x: str(x[1][column]), reverse=descending)

    # Extract just the rows in the new order
    return [row for index, row in sorted_indexed]

  remove(id) {
    // Check if meeting exists
    const meeting = this.meetingMap.get(id);
    if (!meeting) {
      return false;
    }

    // Remove from meetings array
    const index = this.meetings.indexOf(meeting);
    if (index !== -1) {
      this.meetings.splice(index, 1);
    }

    // Remove from meetingMap
    this.meetingMap.delete(id);

    return true;
  }

  move(id, newStart) {
    // Validate newStart
    if (!Number.isInteger(newStart) || newStart < 0 || newStart >= 1440) {
      throw new Error('Start must be an integer between 0 and 1439');
    }

    // Check if meeting exists
    const meeting = this.meetingMap.get(id);
    if (!meeting) {
      throw new Error('Unknown ID');
    }

    // Calculate duration
    const duration = meeting.end - meeting.start;
    const newEnd = newStart + duration;

    // Validate newEnd
    if (newEnd > 1440) {
      throw new Error('Meeting would extend beyond the day');
    }

    // Check for overlapping meetings (excluding the meeting being moved)
    const overlapping = this.conflicts(newStart, newEnd);
    // Remove the current meeting from the overlapping list if it's there
    const filteredOverlapping = overlapping.filter(overlappingId => overlappingId !== id);

    if (filteredOverlapping.length > 0) {
      throw new Error('Meeting overlaps with existing meeting(s): ' + filteredOverlapping.join(', '));
    }

    // Update the meeting
    meeting.start = newStart;
    meeting.end = newEnd;

    // Re-sort the meetings array
    this.meetings.sort((a, b) => {
      if (a.start !== b.start) {
        return a.start - b.start;
      }
      return a.id.localeCompare(b.id);
    });
  }
